<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useI18n } from 'vue-i18n'
import Avatar from 'primevue/avatar'; import AvatarGroup from 'primevue/avatargroup'; import Button from 'primevue/button'; import Column from 'primevue/column'; import DataTable from 'primevue/datatable'; import Dialog from 'primevue/dialog'; import InputText from 'primevue/inputtext'; import Select from 'primevue/select'
import AsyncContent from '@/components/common/AsyncContent.vue'; import PageHeader from '@/components/common/PageHeader.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'; import { useAsyncData } from '@/composables/useAsyncData'; import { getTeam } from '@/services/workspace'

const { t, locale } = useI18n(); const inviteOpen=ref(false); const query=ref(''); const teamFilter=ref('all')
const { data: members, loading, error, load } = useAsyncData(getTeam)
const filtered = computed(() => (members.value||[]).filter(item => (teamFilter.value==='all'||item.teamKey===teamFilter.value) && t(item.nameKey).toLowerCase().includes(query.value.trim().toLowerCase())))
const formatDate = (value:string) => new Intl.DateTimeFormat(locale.value, {year:'numeric',month:'short',day:'numeric'}).format(new Date(`${value}T00:00:00`))
onMounted(load)
</script>

<template><PageHeader :title="$t('team.title')" :description="$t('team.description')"><template #actions><AvatarGroup><Avatar v-for="item in members?.slice(0,3)" :key="item.id" :label="item.initials" shape="circle" /></AvatarGroup><Button :label="$t('team.invite')" icon="pi pi-user-plus" @click="inviteOpen=true" /></template></PageHeader><AsyncContent :loading="loading" :error="error" :empty="!members?.length" @retry="load"><section class="workspace-panel"><div class="mb-4 flex flex-wrap gap-2"><span class="p-input-icon-left flex-1"><i class="pi pi-search" /><InputText v-model="query" class="w-full" :placeholder="$t('team.search')" /></span><Select v-model="teamFilter" :options="[{label:$t('common.all'),value:'all'},{label:$t('team.product'),value:'samples.teams.design'},{label:$t('team.engineering'),value:'samples.teams.engineering'}]" option-label="label" option-value="value" :placeholder="$t('team.filter')" /></div><DataTable :value="filtered" paginator :rows="8"><Column :header="$t('team.member')"><template #body="{data:item}"><div class="flex items-center gap-3"><Avatar :label="item.initials" shape="circle" /><strong>{{ $t(item.nameKey) }}</strong></div></template></Column><Column :header="$t('team.role')"><template #body="{data:item}">{{ $t(`roles.${item.role}`) }}</template></Column><Column :header="$t('team.group')"><template #body="{data:item}">{{ $t(item.teamKey) }}</template></Column><Column :header="$t('team.status')"><template #body="{data:item}"><StatusBadge :label="$t(`presence.${item.status}`)" :severity="item.status==='online'?'success':'secondary'" /></template></Column><Column :header="$t('team.joined')"><template #body="{data:item}">{{ formatDate(item.joined) }}</template></Column></DataTable></section></AsyncContent><Dialog v-model:visible="inviteOpen" modal :header="$t('team.invite')" class="w-[440px] max-w-[90vw]"><div class="grid gap-4"><label class="form-field"><span>{{ $t('team.email') }}</span><InputText type="email" placeholder="name@company.com" /></label><label class="form-field"><span>{{ $t('team.role') }}</span><Select :options="[$t('roles.admin'),$t('roles.member')]" /></label></div><template #footer><Button :label="$t('common.cancel')" text @click="inviteOpen=false" /><Button :label="$t('team.sendInvite')" @click="inviteOpen=false" /></template></Dialog></template>
